"use client";

import { Alert, Spinner } from "flowbite-react";
import { useEffect, useRef, useState } from "react";

import CardBox from "@/shared/ui/cards/CardBox";

import { PurchaseOrdersApi } from "../api/client";
import {
  getLocalPurchaseOrder,
  upsertLocalPurchaseOrder,
} from "../lib/localPurchaseOrders";
import {
  mapPurchaseOrderLineItems,
  mergeLineItemDrawdown,
  toPurchaseOrderDetail,
  toPurchaseOrderRow,
} from "../lib/purchaseOrders";
import type { PurchaseOrderItemTab } from "../lib/deepLinks";
import type { PurchaseOrderDetail, PurchaseOrderItem } from "../types";
import PurchaseOrderDetails from "./PurchaseOrderDetails";

// The PO details body, decoupled from any route/URL.
//
// Two ways to supply the PO header:
//  - `detail` — the already-resolved header (the grid's bottom panel passes the
//    selected row's detail, so the header needs no fetch).
//  - `po` — a PO number only (the standalone deep-link page). We resolve the
//    header from the `getPO` list.
//
// Line items are loaded separately via `getPoDetails` (keyed on POCo + PO) for
// the selected PO and merged into the displayed detail, so the bottom pop-up
// populates with that PO's line items. POs created/edited in-app keep their
// items in the local store and win over the fetch.

interface PurchaseOrderDetailsViewProps {
  po?: string | null;
  // Pre-resolved header — when provided, used directly (no fetch).
  detail?: PurchaseOrderDetail | null;
  // In the grid's bottom panel, focus the body on the line items.
  itemFocused?: boolean;
  // Deep-link arrival (standalone page): open this line-item tab on mount.
  initialTab?: PurchaseOrderItemTab;
  // Deep-link arrival (standalone page): scroll to + flash this line item.
  pendingItemNo?: string | null;
  // When provided, item edits call this instead of the internal local-store
  // handler — the batch-entry screen passes its own server-first handler so
  // line-item creates/edits/deletes reach Vista instead of `localPurchaseOrders`.
  onItemsChange?: (items: PurchaseOrderItem[]) => void;
  // Renders every line-item tab read-only (Info / Costs / Notes) and the items
  // grid non-editable, by withholding the local-store fallback handler below.
  // The posted-PO views (the grid's bottom panel and the standalone details
  // route) set this — a posted purchase order is final and edited in Viewpoint,
  // not here. The PO Entry screen leaves it off and supplies a real
  // `onItemsChange` so its lines stay editable.
  readOnly?: boolean;
}

export default function PurchaseOrderDetailsView({
  po,
  detail: detailProp,
  itemFocused = false,
  initialTab,
  pendingItemNo,
  onItemsChange: onItemsChangeProp,
  readOnly = false,
}: PurchaseOrderDetailsViewProps) {
  const [detail, setDetail] = useState<PurchaseOrderDetail | null>(
    detailProp ?? null,
  );
  // Only the deep-link path (po, no detail prop) fetches the header.
  const [loading, setLoading] = useState(!detailProp && Boolean(po));
  const [error, setError] = useState<string | null>(null);

  // Line items fetched via getPoDetails for the resolved PO, or null until the
  // fetch resolves. Seeded from the header detail's own items (set for in-app
  // POs) so locally-created orders show their lines immediately.
  const [lineItems, setLineItems] = useState<PurchaseOrderItem[] | null>(
    detailProp?.items ?? null,
  );

  // NOTE: this view deliberately does NOT re-read the Vista attachment group id
  // off the `getPoDetails` header. An earlier revision did, on the theory that a
  // posted PO's grid row lacks the id — but both endpoints read the SAME column
  // of the SAME row: `getPO` selects `POHD.UniqueAttchID AS uniqueAttchID`
  // (getPO.js) and `getPoDetails` selects `POHD.UniqueAttchID AS uniqueAttchID`
  // (getPoDetails.js). A header fetch can never supply an id the row it came
  // from didn't already carry, so `detail.uniqueAttchId` is the whole story.
  // Locally-overridden POs don't even reach the fetch (see the local-store
  // short-circuit below), so there is no gap there either.

  // When a resolved detail is supplied, mirror it into state (no fetch).
  useEffect(() => {
    if (detailProp) {
      setDetail(detailProp);
      setLoading(false);
      setError(null);
    }
  }, [detailProp]);

  useEffect(() => {
    if (detailProp) return; // detail supplied directly; nothing to fetch
    let cancelled = false;

    const load = async () => {
      setLoading(true);
      setError(null);
      setDetail(null);

      if (!po) {
        setLoading(false);
        return;
      }

      // POs created/edited in the app live only in the in-memory store.
      const local = getLocalPurchaseOrder(po);
      if (local) {
        setDetail(local.detail);
        setLoading(false);
        return;
      }

      try {
        // Resolve from the header list (the only deployed PO endpoint) and find
        // the matching record by PO number.
        const response = await PurchaseOrdersApi.getPurchaseOrders();
        if (cancelled) return;
        if (response.ok && response.data) {
          const match = response.data.records
            .map(toPurchaseOrderRow)
            .find((row) => row.purchaseOrder === po);
          setDetail(match ? toPurchaseOrderDetail(match) : null);
        } else {
          setError("Failed to load purchase order.");
        }
      } catch (loadError) {
        if (!cancelled) {
          console.error("Failed to load purchase order:", loadError);
          setError("Failed to load purchase order.");
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    };

    void load();
    return () => {
      cancelled = true;
    };
  }, [po, detailProp]);

  // Load the resolved PO's line items from getPoDetails (composite key POCo, PO)
  // and merge them into the detail. Keyed on the PO identity via a ref so the
  // grid re-rendering the detail object (e.g. paging in more rows) doesn't
  // refetch, and switching to a different PO does.
  const detailPoCo = detail?.poCo ?? null;
  const detailPo = detail?.purchaseOrder ?? null;
  const loadedItemsKeyRef = useRef<string | null>(null);
  // Latest header items, read inside the load effect without making it a
  // dependency (refetching is gated on the PO identity, not item edits).
  const detailItemsRef = useRef<PurchaseOrderItem[] | undefined>(detail?.items);
  detailItemsRef.current = detail?.items;
  useEffect(() => {
    if (!detailPo) {
      setLineItems(null);
      loadedItemsKeyRef.current = null;
      return;
    }
    const key = `${detailPoCo ?? ""}|${detailPo}`;
    if (loadedItemsKeyRef.current === key) return;

    // In-app POs keep their line items in the local store; those win over a
    // backend fetch (and a locally-created PO has no backend record to fetch).
    const local = getLocalPurchaseOrder(detailPo);
    if (local) {
      loadedItemsKeyRef.current = key;
      setLineItems(local.detail.items ?? []);
      return;
    }

    // Pending POHB batch orders arrive from `getPOBatch` with their line items
    // already nested on the row. Those POIB lines have no received / invoiced /
    // remaining ledger — that lives on the posted POIT line, served by
    // getPoDetails. So we still fetch: when the batch is a drawdown against an
    // already-posted PO, getPoDetails supplies the ledger and we overlay it onto
    // the carried lines; a brand-new pending entry 404s and the carried lines
    // (blank ledger) stand.
    const carried = detailItemsRef.current;
    const baseItems = carried && carried.length > 0 ? carried : null;

    // getPoDetails needs the PO company. Without it, fall back to whatever items
    // the header detail already carries.
    if (!detailPoCo) {
      loadedItemsKeyRef.current = key;
      setLineItems(baseItems ?? []);
      return;
    }

    let cancelled = false;
    loadedItemsKeyRef.current = key;
    // Show carried lines immediately (no spinner flash) while the ledger loads;
    // a posted PO opened directly has none yet, so fall back to the spinner.
    setLineItems(baseItems);
    const loadItems = async () => {
      try {
        const response = await PurchaseOrdersApi.getPurchaseOrderDetail(
          detailPoCo,
          detailPo,
        );
        if (cancelled) return;
        if (response.ok && response.data) {
          // Only the line items are taken from this response — the header is
          // discarded on purpose (see the attachment-id note near the top).
          const fetched = mapPurchaseOrderLineItems(response.data.lineItems ?? []);
          // Overlay the POIT ledger onto carried batch lines; otherwise the
          // fetched lines are the whole detail (posted PO opened directly).
          setLineItems(baseItems ? mergeLineItemDrawdown(baseItems, fetched) : fetched);
        } else {
          // 404 / error: a not-yet-posted entry. Keep carried lines (blank
          // ledger) or an empty grid rather than break the panel.
          setLineItems(baseItems ?? []);
        }
      } catch (loadError) {
        if (!cancelled) {
          console.error("Failed to load PO line items:", loadError);
          setLineItems(baseItems ?? []);
        }
      }
    };
    void loadItems();
    return () => {
      cancelled = true;
    };
  }, [detailPoCo, detailPo]);

  if (loading) {
    return (
      <CardBox>
        <div className="flex items-center justify-center py-12">
          <Spinner size="lg" />
        </div>
      </CardBox>
    );
  }

  if (error) {
    return (
      <CardBox>
        <Alert color="failure">{error}</Alert>
      </CardBox>
    );
  }

  if (!detail) {
    return (
      <CardBox>
        <p className="text-gray-500 dark:text-gray-400">
          {po
            ? `Purchase order ${po} was not found.`
            : "No purchase order selected. Pick one from the list."}
        </p>
      </CardBox>
    );
  }

  // The header (from prop/fetch) plus the line items loaded via getPoDetails.
  const detailWithItems: PurchaseOrderDetail = {
    ...detail,
    items: lineItems ?? detail.items ?? [],
  };

  // Inline edits from the Items spreadsheet persist as a local override, unless
  // the caller (the batch-entry screen) supplies its own server-first handler.
  // In `readOnly` mode (the posted-PO views) NO handler is supplied at all — not
  // even the local-store fallback — so every line-item tab and the items grid
  // render read-only (see `PurchaseOrderDetails`).
  const handleItemsChange = readOnly
    ? undefined
    : (onItemsChangeProp ??
      ((items: PurchaseOrderDetail["items"]) => {
        const updated = { ...detailWithItems, items };
        upsertLocalPurchaseOrder(updated);
        setDetail(updated);
        setLineItems(items ?? []);
      }));

  // `handleItemsChange` is `undefined` in `readOnly` mode; otherwise it's always
  // set (falling back to the local-store closure when no override is supplied).
  // Either way it can't decide whether adding/deleting a line item actually
  // reaches Vista — only a real caller-supplied override does. The standalone
  // details page and the grid's bottom panel omit `onItemsChangeProp` and (when
  // not read-only) get the local-store fallback, which never persists
  // server-side. Gate the create/delete affordances on that distinction; inline
  // field edits keep using `handleItemsChange` unchanged.
  const itemsEditable = !readOnly && Boolean(onItemsChangeProp);

  return (
    <PurchaseOrderDetails
      purchaseOrder={detailWithItems}
      onItemsChange={handleItemsChange}
      itemsEditable={itemsEditable}
      itemFocused={itemFocused}
      initialTab={initialTab}
      pendingItemNo={pendingItemNo}
    />
  );
}

